    },
    FONLayout: function () {
        Controls.OptionsPane.Hide(false);
        Controls.ComplianceScore__.Hide(true);
        Controls.CompanyInformation__.Hide(true);
        Controls.ScoringAgencyHomePage__.SetValue("");
